import React, { useEffect, useState } from "react";
import Store from './store';
import styles from './index.module.less';
import { Button, Collapse, Divider, Drawer, Empty, Link, List, Message, Popover, Result, Space, Spin, Tag, Tree, TreeSelect } from "@arco-design/web-react";
import { useObserver } from "mobx-react-lite";
import i18next from "i18next";
import { IfrmaeWindowProps } from "@/types/iframe";
import page from "@/store/page";



export const settingStore = Store;
const win: IfrmaeWindowProps = window as any;

interface SettingProps {
    store: Store;
}


const Settings = ({ store }: SettingProps) => {


    const iframeWindow: any = store.iframeRef.current?.contentWindow;


    useEffect(() => {
        if(iframeWindow){
            store.setPathname(iframeWindow.location.hash)
            iframeWindow.addEventListener('hashchange', function() {
                store.setPathname(iframeWindow.location.hash);
            });
        }
    },[iframeWindow])

    return useObserver(() => {


        return (
            <div className={styles.header}>
                <div>
                    切换路由
                    <Popover
                        position='bl'
                        trigger="click"
                        content={(
                            <div className="min-w-80">
                                <Tree
                                    blockNode
                                    className="w-full"
                                    autoExpandParent
                                    fieldNames={{
                                        key: "path",
                                        title: "name"
                                    }}
                                    onSelect={(keys, extra) => {
                                        const { dataRef: item }: any = extra.node.props
                                    }}
                                    treeData={win? win.dev.routes : []}
                                    renderTitle={({ title, dataRef, ...props }) => {
                                        return `${i18next.t(title as string)}(${dataRef.path})`
                                    }}
                                />
                            </div>
                        )}
                    >
                        <Button type="text" size="small" >
                            URL：{store.pathname}
                        </Button>
                    </Popover>
                </div>
                <div>
                    <Button
                        onClick={() => {
                            store.setIsReady(false);
                            setTimeout(() => {
                                store.setIsReady(true);
                            },300)
                        }}
                    >刷新</Button>
                </div>
            </div>
        )

    })

}


export default Settings;