import { UserInfo } from "@/types/user";
import ajax from "@/utils/ajax";
import { action, observable, makeObservable } from "mobx";
import userStore from "@code/store/user";
import { IfrmaeAppProps } from "@/types/iframe";
import React from "react";


const win: IfrmaeAppProps = window as any;

const { pageStore } = win;
class Store {

    iframeRef = React.createRef<any>();


    @observable pathname = "#/";
    @action setPathname = (path) => {
        this.pathname = path;
    }

    @observable key = Date.now();

    /**
     * 当前iframe 窗口是否加载成功
     */
    @observable isFrameReady = false;
    @action setIsFrameReady = (bool: boolean) => {
        this.isFrameReady = bool;
        this.key = Date.now();
    }

    /**
     * 当前主窗口是否加载成功
     */
    @observable isReady = false;
    @action setIsReady = (bool: boolean) => {
        this.isReady = bool;
    }


    /**
     * 获取菜单列表
     */
    getMenuList = async () => {
        if(pageStore){
            return pageStore.getMenuList();
        }
    }


    init = async () => {
        // 获取菜单信息
        await this.getMenuList();
        this.setIsReady(true);
    }

    constructor(){
        makeObservable(this);
        this.init();
    }

}


export default Store;